{
  "name": "@aberigle/opencode-go-usage",
  "version": "0.3.0",
  "description": "OpenCode 2 TUI sidebar with OpenCode Go token usage and cost per model across the rolling, weekly and monthly windows.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-go",
    "tui",
    "usage",
    "cost"
  ],
  "license": "MIT",
  "author": "aberigle",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/aberigle/opencode-go-usage.git"
  },
  "type": "module",
  "publishConfig": {
    "access": "public"
  },
  "files": [
    "tui.ts",
    "dist"
  ],
  "scripts": {
    "build": "bun run build.ts",
    "typecheck": "bun run build && tsc --noEmit -p .",
    "prepublishOnly": "bun run build"
  },
  "devDependencies": {
    "@opencode/plugin": "^2.0.20",
    "@opencode/theme": "^2.0.20",
    "@opentui/core": "^0.5.13",
    "@opentui/solid": "^0.5.13",
    "solid-js": "^1.9.15",
    "@types/bun": "^1.4.2"
  },
  "dependencies": {
    "xdg-basedir": "^5.1.0"
  }
}
